async function charge(orderId: string, amountCents: number): Promise<void> {
    while (true) {
        try {
            await fetch("https://payments.internal/charge", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ orderId, amountCents }),
            });
            return;
        } catch {
            continue;
        }
    }
}
